#!/bin/bash
set -e

# If we have AWS credentials in environment variables, use them. But only if we don't have a role ARN
# If we have a role ARN, assume the role with the web identity token regardless of the environment variables
if [ -n "$AWS_ACCESS_KEY_ID" ] && [ -z "$ROLE_ARN" ]; then
    mkdir -p ~/.aws
    touch ~/.aws/credentials
    chmod 700 ~/.aws/credentials
    echo "[default]" >>~/.aws/credentials
    echo "aws_access_key_id=$AWS_ACCESS_KEY_ID" >>~/.aws/credentials
    echo "aws_secret_access_key=$AWS_SECRET_ACCESS_KEY" >>~/.aws/credentials
    echo "echo Have AWS credentials in environment variables, creating credential file"
else
    # Define ROLE_ARN if not already defined
    [ -z "$ROLE_ARN" ] && export ROLE_ARN=arn:aws:iam::`npx get-deploy-account`:role/GitLabOidcRole

    echo export $(printf "AWS_ACCESS_KEY_ID=%s AWS_SECRET_ACCESS_KEY=%s AWS_SESSION_TOKEN=%s" \
        $(aws sts assume-role-with-web-identity \
        --role-arn ${ROLE_ARN} \
        --role-session-name "GitLabRunner-${CI_PROJECT_ID}-${CI_PIPELINE_ID}" \
        --web-identity-token ${GITLAB_OIDC_TOKEN} \
        --duration-seconds 3600 \
        --query 'Credentials.[AccessKeyId,SecretAccessKey,SessionToken]' \
        --output text))
fi